-- department categorization
CREATE TABLE `T_CK_CT_DEPT` (
  `DEPT_ID` varchar(35) NOT NULL COMMENT 'RECORD ID - UUID',
  `DEPT_ACCN` varchar(35) DEFAULT NULL COMMENT 'ACCOUNT - REFERENCES T_CORE_ACCN:ACCN_ID',
  `DEPT_NAME` varchar(256) DEFAULT NULL COMMENT 'DEPARTMENT NAME',
  `DEPT_DESC` varchar(1024) DEFAULT NULL COMMENT 'DEPARTMENT DESCRIPTION',
  `DEPT_COLOR` char(1) DEFAULT NULL COMMENT 'COLOR CODE - 1..9',
  `DEPT_STATUS` char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  `DEPT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DEPT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DEPT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DEPT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DEPT_ID`),
  CONSTRAINT `FK_CK_CT_DEPT_CORE_ACCN` FOREIGN KEY (`DEPT_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DEPARTMENT TABLE';


CREATE TABLE `T_CK_CT_DEPT_USR` (
  `DU_ID` varchar(35) NOT NULL COMMENT 'RECORD ID - UUID',
  `DU_DEPT` varchar(35) DEFAULT NULL COMMENT 'DEPARTMENT - REFERENCES T_CK_CT_DEPT:DEPT_ID',
  `DU_USR` varchar(35) DEFAULT NULL COMMENT 'DEPARTMENT USER - REFERENCES T_CORE_USR:USR_UID',
  `DU_STATUS` char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  `DU_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DU_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DU_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DU_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DU_ID`),
  CONSTRAINT `FK_CK_CT_DU_CK_CT_DEPT` FOREIGN KEY (`DU_DEPT`) REFERENCES `T_CK_CT_DEPT` (`DEPT_ID`),  
  CONSTRAINT `FK_CK_CT_DU_CORE_USR` FOREIGN KEY (`DU_USR`) REFERENCES `T_CORE_USR` (`USR_UID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DEPARTMENT USERS TABLE';


CREATE TABLE `T_CK_CT_DEPT_VEH` (
  `DV_ID` varchar(35) NOT NULL COMMENT 'RECORD ID - UUID',
  `DV_DEPT` varchar(35) DEFAULT NULL COMMENT 'DEPARTMENT - REFERENCES T_CK_CT_DEPT:DEPT_ID',
  `DV_VEH` varchar(35) DEFAULT NULL COMMENT 'DEPARTMENT USER - REFERENCES T_CK_CT_VEH:VH_ID',
  `DV_STATUS` char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  `DV_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DV_ID`),
  CONSTRAINT `FK_CK_CT_DV_CK_CT_DEPT` FOREIGN KEY (`DV_DEPT`) REFERENCES `T_CK_CT_DEPT` (`DEPT_ID`),  
  CONSTRAINT `FK_CK_CT_DV_CORE_USR` FOREIGN KEY (`DV_VEH`) REFERENCES `T_CK_CT_VEH` (`VH_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DEPARTMENT VEHICLE TABLE';

