DROP TABLE IF EXISTS T_CK_JOB_UPLOAD;

CREATE TABLE `T_CK_JOB_UPLOAD` (
  `UP_ID` varchar(35) NOT NULL COMMENT 'RECORD FILE LOG ID - UUID',
  `UP_ACCN_ID` varchar(35) DEFAULT NULL COMMENT 'ACCOUNT ID',
  `UP_FILE_NAME` varchar(256) DEFAULT NULL COMMENT 'EXCEL FILE NAME',
  `UP_FILE_PATH` varchar(512) DEFAULT NULL COMMENT 'EXCEL FILE NAME AND PATH IN LOCAL',
  `UP_FILE_SIZE` int DEFAULT NULL COMMENT 'EXCEL FILE LEGNTH',
  `UP_TOTAL_LINES` int DEFAULT NULL COMMENT 'EXCEL FILE TOTAL LINES',
  `UP_SUCCESS_JOB_IDS` varchar(2048) DEFAULT NULL COMMENT 'SUCCESS LINES AND JOBID: 2:JOBID, 4:JOBID, 6:JOBID, 8:JOBID',
  `UP_FAIL_LINES` varchar(2048) DEFAULT NULL COMMENT 'FAILED LINES: 1,3,5,7',
  `UP_REMARK` varchar(2048) DEFAULT NULL,
  `UP_STATUS` char(1) DEFAULT NULL COMMENT 'OPM STATE STATUS',
  `UP_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `UP_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `UP_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `UP_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`UP_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB UPLOAD LOG TABLE';

