-- Shell card integration
CREATE TABLE `T_CK_CT_SHELL_CARD` (
  `SC_ID` varchar(35) NOT NULL COMMENT 'CARD ID',
  `SC_DT_EXPIRY` datetime DEFAULT NULL COMMENT 'CARD EXPIRY DATE',
  `SC_STATUS` char(1) DEFAULT NULL COMMENT 'CARD STATUS - A:ACTIVE I:EXPIRED',
  `SC_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SC_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SC_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SC_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SC_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL CARD TABLE';


CREATE TABLE `T_CK_CT_SHELL_KIOSK` (
  `SK_ID` varchar(35) NOT NULL COMMENT 'KIOSK ID',
  `SK_NAME` varchar(1024) DEFAULT NULL COMMENT 'KIOSK NAME',
  `SK_STATUS` char(1) DEFAULT NULL COMMENT 'KIOSK STATE STATUS - A:ACTIVE I:EXPIRED',
  `SK_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SK_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SK_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SK_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SK_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL KIOSK TABLE';


CREATE TABLE `T_CK_CT_SHELL_BATCH_WINDOW` (
  `SB_ID` varchar(35) NOT NULL COMMENT 'BATCH ID - UNIQUE ID',
  `SB_NAME` varchar(1024) DEFAULT NULL COMMENT 'BATCH NAME',
  `SB_DT_WINDOW` datetime DEFAULT NULL COMMENT 'BATCH WINDOW',
  `SB_STATUS` char(1) DEFAULT NULL COMMENT 'BATCH STATUS - A:ACTIVE I:EXPIRED',
  `SB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`SB_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL BATCH WINDOW TABLE';


CREATE TABLE `T_CK_CT_SHELL_TXN` (
  `ST_ID` varchar(35) NOT NULL COMMENT 'TXN ID - UNIQUE ID',
  `ST_CARD` varchar(35) DEFAULT NULL COMMENT 'CARD PAN NUMBER - REFERENCE T_CK_CT_SHELL_CARD:SC_ID',
  `ST_ACCN` varchar(35) DEFAULT NULL COMMENT 'CARD ASSOICATED ACCOUNT - REFERENCE T_CORE_ACCN:ACCN_ID',  
  `ST_QTY` decimal(8,2) DEFAULT 0.0 COMMENT 'TXN QUANTITY',
  `ST_PRODUCT` varchar(512) DEFAULT NULL COMMENT 'TXN PRODUCT NAME',
  `ST_TXN_ID` varchar(256) DEFAULT NULL COMMENT 'TXN ID FROM SHELL',
  `ST_TXN_DATE` datetime DEFAULT NULL COMMENT 'TXN DATE TIME',
  `ST_INV_NET` decimal(15,2) DEFAULT 0.0 COMMENT 'TXN INVOICE NET - BEFORE TAX',
  `ST_INV_GROSS` decimal(15,2) DEFAULT 0.0 COMMENT 'TXN INVOICE GROSS - AFTER TAX',
  `ST_CRV_NET` decimal(15,2) DEFAULT 0.0 COMMENT 'CUSTOMER RETAIL VALUE NET - BEFORE TAX',
  `ST_CRV_GROSS` decimal(15,2) DEFAULT 0.0 COMMENT 'CUSTOMER RETAIL VALUE GROSS - AFTER TAX',
  `SB_STATUS` char(1) DEFAULT NULL COMMENT 'BATCH STATUS - A:ACTIVE I:EXPIRED',
  `SB_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SB_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `SB_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `SB_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ST_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_TXN_CK_CT_SHELL_CARD` FOREIGN KEY (`ST_CARD`) REFERENCES `T_CK_CT_SHELL_CARD` (`SC_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_TXN_CORE_ACCN` FOREIGN KEY (`ST_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL TXN TABLE';


CREATE TABLE `T_CK_CT_SHELL_CARD_TRUCK` (
  `CT_ID` varchar(35) NOT NULL COMMENT 'ASSIGNMENT ID - UUID',
  `CT_ACCN` varchar(35) DEFAULT NULL COMMENT 'ACCN - REFERENCES T_CORE_ACCN:ACCN_ID',
  `CT_TRUCK` varchar(35) DEFAULT NULL COMMENT 'TRUCK - REFERENCES T_CK_CT_VEH:VH_ID',
  `CT_CARD` varchar(35) DEFAULT NULL COMMENT 'CARD - REFERENCES T_CK_CT_SHELL_CARD:SC_ID',
  `CT_STATUS` char(1) DEFAULT NULL COMMENT 'ASSIGNMENT STATUS - A:ACTIVE I:INACTIVE',
  `CT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CT_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_CARD_TRUCK_CORE_ACCN` FOREIGN KEY (`CT_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_CARD_TRUCK_CK_CT_VEH` FOREIGN KEY (`CT_TRUCK`) REFERENCES `T_CK_CT_VEH` (`VH_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_CARD_TRUCK_CK_CT_SHELL_CARD` FOREIGN KEY (`CT_CARD`) REFERENCES `T_CK_CT_SHELL_CARD` (`SC_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL CARD ASSIGNMENT TABLE';


CREATE TABLE `T_CK_CT_SHELL_INVOICE` (
  `INV_ID` varchar(35) NOT NULL COMMENT 'INVOICE ID - UNIQUE ID',
  `INV_NO` varchar(256) DEFAULT NULL COMMENT 'INVOICE NUMNER',
  `INV_ACCN` varchar(35) DEFAULT NULL COMMENT 'CARD ASSOICATED ACCOUNT - REFERENCE T_CORE_ACCN:ACCN_ID',  
  `INV_DT` datetime DEFAULT NULL COMMENT 'INVOICE DATE',
  `INV_AMT` decimal(15,2) DEFAULT 0.0 COMMENT 'INVOICE AMT', 
  `INV_PAYMENT_DT` datetime DEFAULT NULL COMMENT 'INVOICE PAYMENT DATE',
  `INV_PAYMENT_AMT` decimal(15,2) DEFAULT 0.0 COMMENT 'PAYMENT AMT', 
  `INV_BALANCE_AMT` decimal(15,2) DEFAULT 0.0 COMMENT 'BALANCE AMT', 
  `INV_STATUS` char(1) DEFAULT NULL COMMENT 'INVOICE STATUS - A:ACTIVE P:APID',
  `INV_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `INV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `INV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `INV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`INV_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_INVOICE_CORE_ACCN` FOREIGN KEY (`INV_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL INVOICE TABLE';


CREATE TABLE `T_CK_CT_SHELL_INVOICE_ITEM` (
  `ITM_ID` varchar(35) NOT NULL COMMENT 'INVOICE ITEM ID - UNIQUE ID',
  `ITM_INV` varchar(256) DEFAULT NULL COMMENT 'INVOICE - REFERENCE T_CK_CT_SHELL_INVOICE:INV_ID',
  `ITM_TRUCK` varchar(35) DEFAULT NULL COMMENT 'TRUCK - REFERENCES T_CK_CT_VEH:VH_ID',
  `ITM_CARD` varchar(35) DEFAULT NULL COMMENT 'CARD - REFERENCES T_CK_CT_SHELL_CARD:SC_ID',
  `ITM_DESC` varchar(512) DEFAULT NULL COMMENT 'ITEM DESCRIPTION',
  `ITM_DT_TXN` datetime DEFAULT NULL COMMENT 'TRANSACTION DATE TIME',
  `ITM_COST` decimal(15,2) DEFAULT 0.0 COMMENT 'ITEM COST',
  `ITM_DISCOUNT` decimal(15,2) DEFAULT 0.0 COMMENT 'DISCOUNT AMOUNT',
  `ITM_TAX` decimal(15,2) DEFAULT 0.0 COMMENT 'TAX AMOUNT',
  `ITM_CO2` decimal(15,2) DEFAULT 0.0 COMMENT 'CO2 COMPENSATION FEE',
  `ITM_TOTAL` decimal(15,2) DEFAULT 0.0 COMMENT 'TOTAL AMOUNT FOR ITEM LINE',
  `ITM_STATUS` char(1) DEFAULT NULL COMMENT 'INVOICE STATUS - A:ACTIVE P:APID',
  `ITM_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ITM_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ITM_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ITM_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ITM_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_INVOICE_ITEM_CK_CT_SHELL_INVOICE` FOREIGN KEY (`ITM_INV`) REFERENCES `T_CK_CT_SHELL_INVOICE` (`INV_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_INVOICE_ITEM_CK_CT_VEH` FOREIGN KEY (`ITM_TRUCK`) REFERENCES `T_CK_CT_VEH` (`VH_ID`),
  CONSTRAINT `FK_CK_CT_SHELL_INVOICE_ITEM_CK_CT_SHELL_CARD` FOREIGN KEY (`ITM_CARD`) REFERENCES `T_CK_CT_SHELL_CARD` (`SC_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SHELL INVOICE ITEM TABLE';


