CREATE TABLE `T_CK_CT_RENTAL_APP` (
    `VR_ID` varchar(35) NOT NULL COMMENT 'RENTAL ID - UUID',
    `VR_ACCN` varchar(35) DEFAULT NULL COMMENT 'ACCN INTIATING THE RENTAL - REFERENCES T_CORE_ACCN:ACCN_ID',
    `VR_PROVIDER` varchar(256) DEFAULT NULL COMMENT 'RENTAL PROVIDER',
    `VR_TRUCK` varchar(256) DEFAULT NULL COMMENT 'RENTAL TRUCK',
    `VR_LEASE` smallint DEFAULT 0 COMMENT 'RENTAL LEASE PERIOD',
    `VR_PRICE` decimal(15,2) DEFAULT 0.0 COMMENT 'RENTAL PRICE',
    `VR_QTY` smallint DEFAULT 0 COMMENT 'RENTAL QUANTITY',
    `VR_CT_NAME` varchar(256) DEFAULT NULL COMMENT 'CONTACT NAME',
    `VR_CT_MOBILE` varchar(256) DEFAULT NULL COMMENT 'CONTACT MOBILE',
    `VR_CT_EMAIL` varchar(256) DEFAULT NULL COMMENT 'CONTACT EMAIL',
    `VR_STATUS` char(1) DEFAULT NULL COMMENT 'VEHICLE STATE STATUS – N:NEW S:SUCCESS R:REJCTED',
    `VR_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
    `VR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
    `VR_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
    `VR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
    PRIMARY KEY (`VR_ID`),
    CONSTRAINT `FK_CK_CT_RENTAL_CORE_ACCN` FOREIGN KEY (`VR_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='VEHICLE RENTAL APPLICATION TABLE';

