CREATE TABLE `T_CK_CT_EPOD_TEMPLATE` (
  `EPOD_ID` varchar(70) NOT NULL,
  `EPOD_ACCN_FF` varchar(70) DEFAULT NULL,
  `EPOD_ACCN_TO` varchar(70) DEFAULT NULL,
  `EPOD_ACCN_CO` varchar(70) DEFAULT NULL,
  `EPOD_EPOD_JRXML` varchar(256) DEFAULT NULL COMMENT 'EPOD JRXML FILE PATH',
  `EPOD_EPOD_LOGO` varchar(256) DEFAULT NULL COMMENT 'EPOD LOGO FILE PATH',
  `EPOD_EPOD_SUB_REPORT` varchar(256) DEFAULT NULL COMMENT 'EPOD JRXML SUB REPORT',
  `EPOD_EPOD_SERVICE` varchar(256) DEFAULT NULL COMMENT 'EPOD SPRING BEEN SERVICE NAME',
  `EPOD_STATUS` char(1) NOT NULL,
  `EPOD_DT_CREATE` datetime NOT NULL COMMENT 'Contains the date where this record is created.',
  `EPOD_UID_CREATE` varchar(35) NOT NULL COMMENT 'Contains the User ID that create this record.',
  `EPOD_DT_LUPD` datetime DEFAULT NULL COMMENT 'Contains the date where this record is last updated.',
  `EPOD_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Contains the User ID that last update this record.',
  PRIMARY KEY (`EPOD_ID`),
  CONSTRAINT `FKY_EPOD_ACCN_FF` FOREIGN KEY (`EPOD_ACCN_FF`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FKY_EPOD_ACCN_TO` FOREIGN KEY (`EPOD_ACCN_TO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FKY_EPOD_ACCN_CO` FOREIGN KEY (`EPOD_ACCN_CO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

