-- 01/30/2025 UPDATE SCRIPT REPORTS TO FLAG NEW JOBS AS REJECTED IF THE JOB CONTAINS REMARKS
UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_NAME` = 'All Trucking Jobs', `RPTT_WIDTH_PERC` = 100.0000, `RPTT_SHOW` = 'Y', `RPTT_COLS` = 0, `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\r\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\r\n          TRUCK.JOB_SHIPMENT_REF                                      AS SHIPPING_REF,\r\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\r\n           CASE \r\n             WHEN REMARKS.JOBR_DT_REMARKS IS NOT NULL AND STATE.JBST_DESC = \'NEW\' THEN \'REJECTED\' \r\n               ELSE STATE.JBST_NAME END AS JOB_STATE,\r\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\r\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\r\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\r\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\r\n          ( CASE\r\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\r\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\r\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\r\n              ELSE TRUCK.JOB_DRV\r\n            END )                                                    AS DRV_NAME,\r\n          ( CASE\r\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\r\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\r\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\r\n              ELSE TRUCK.JOB_VEH\r\n            END )                                                    AS VH_PLATE_NO,\r\n		  ( CASE\r\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\r\n            END )  AS PROCESS_VIA,\r\n            \r\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\'), \'-\') AS RCD_DT_SUBMIT,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\'), \'-\') AS RCD_DT_CANCEL,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\'), \'-\') AS RCD_DT_ACCEPTED,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\'), \'-\') AS RCD_DT_START,\r\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE\r\n   FROM   T_CK_JOB_TRUCK TRUCK\r\n          LEFT JOIN T_CK_JOB JOB\r\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\r\n          LEFT JOIN T_CK_CT_TRIP TRIP\r\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\r\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\r\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\r\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\r\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\r\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\r\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\r\n          LEFT JOIN T_CORE_ACCN TO_ACCN\r\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\r\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\r\n                 ON JOB.JOB_STATE = STATE.JBST_ID\r\n          LEFT JOIN T_CK_RECORD_DATE RECORD\r\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\r\n          LEFT JOIN T_CK_JOB_REMARKS REMARKS ON REMARKS.JOBR_JOB = JOB.JOB_ID\r\n WHERE  \r\n    TRUCK.JOB_PARTY_TO = \'@ACCNID@\'\r\n        AND (\r\n        \'@FIL_JOB_STATE_CAP@\' = \'ALL\' \r\n        OR (JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\r\n					OR (\r\n						JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\r\n						AND (\r\n							CASE \r\n									WHEN JOB.JOB_STATE = \'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_CANCEL_FROM@\' AND \'@FIL_RCD_DT_CANCEL_TO@\'\r\n									WHEN JOB.JOB_STATE = \'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_COMPLETE_FROM@\' AND \'@FIL_RCD_DT_COMPLETE_TO@\'\r\n									WHEN JOB.JOB_STATE = \'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_ACCEPTED_FROM@\' AND \'@FIL_RCD_DT_ACCEPTED_TO@\'\r\n									WHEN JOB.JOB_STATE = \'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_START_FROM@\' AND \'@FIL_RCD_DT_START_TO@\'\r\n									ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_SUBMIT_FROM@\' AND \'@FIL_RCD_DT_SUBMIT_TO@\'\r\n							END\r\n					)\r\n				)\r\n			)\r\n    )\r\n		AND (\r\n			CASE \r\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'WEB\' THEN (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL)\r\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'MOBILE\' THEN TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\'\r\n			 ELSE (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL) END\r\n          )' WHERE `RPTT_RPTID` = 'RPT_ALL_JOBS_TO' AND `RPTT_ACCN_TYPE` = 'ACC_TYPE_TO' AND `RPTT_TBL_IDX` = 0;

-- 02/10/2025 Create table to store value UOMs
CREATE TABLE `T_CK_CT_MST_UOM_WEIGHT` (
  `WEI_ID` VARCHAR(35) NOT NULL COMMENT 'WEIGHT ID - UUID',
  `WEI_NAME` VARCHAR(35) NOT NULL COMMENT 'WEIGHT NAME',
  `WEI_DESC` VARCHAR(35) NOT NULL COMMENT 'WEIGHT DESCRIPTION - UUID',
  `WEI_STATUS` ENUM('A', 'I') DEFAULT 'A' COMMENT 'RECORD STATUS - A: Active, I: Inactive',
  `WEI_DT_CREATE` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT 'RECORD CREATED DATE',
  `WEI_UID_CREATE` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `WEI_DT_LUPD` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'RECORD LAST UPDATED DATE',
  `WEI_UID_LUPD` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`WEI_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TABLE FOR UOM WEIGHT';

CREATE TABLE `T_CK_CT_MST_UOM_VOLUME` (
  `VOL_ID` VARCHAR(35) NOT NULL COMMENT 'VOLDOR ID - UUID',
  `VOL_NAME` VARCHAR(35) NOT NULL COMMENT 'VOLUME NAME',
  `VOL_DESC` VARCHAR(35) NOT NULL COMMENT 'VOLDOR ID - UUID',
  `VOL_STATUS` ENUM('A', 'I') DEFAULT 'A' COMMENT 'RECORD STATUS - A: Active, I: Inactive',
  `VOL_DT_CREATE` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT 'RECORD CREATED DATE',
  `VOL_UID_CREATE` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `VOL_DT_LUPD` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'RECORD LAST UPDATED DATE',
  `VOL_UID_LUPD` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`VOL_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TABLE FOR UOM VOLUME';

CREATE TABLE `T_CK_CT_MST_UOM_SIZE` (
    `SIZ_ID` VARCHAR(35) NOT NULL COMMENT 'SIZE ID - UUID',
    `SIZ_NAME` VARCHAR(35) NOT NULL COMMENT 'SIZE NAME',
    `SIZ_DESC` VARCHAR(35) NOT NULL COMMENT 'SIZE ID - UUID',
    `SIZ_STATUS` ENUM('A', 'I') DEFAULT 'A' COMMENT 'RECORD STATUS - A: Active, I: Inactive',
    `SIZ_DT_CREATE` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT 'RECORD CREATED DATE',
    `SIZ_UID_CREATE` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
    `SIZ_DT_LUPD` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'RECORD LAST UPDATED DATE',
    `SIZ_UID_LUPD` VARCHAR(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
    PRIMARY KEY (`SIZ_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TABLE FOR UOM SIZE';

-- Add columns for the new references
ALTER TABLE `T_CK_CT_TRIP_CARGO_MM`
    ADD COLUMN `CG_CARGO_UOM_WEIGHT` VARCHAR(35) DEFAULT NULL COMMENT 'UOM WEIGHT - REFERENCES T_CK_CT_MST_UOM_WEIGHT:WEI_ID',
    ADD COLUMN `CG_CARGO_UOM_VOLUME` VARCHAR(35) DEFAULT NULL COMMENT 'UOM VOLUME - REFERENCES T_CK_CT_MST_UOM_VOLUME:VOL_ID',
    ADD COLUMN `CG_CARGO_UOM_SIZE` VARCHAR(35) DEFAULT NULL COMMENT 'UOM SIZE - REFERENCES T_CK_CT_MST_UOM_SIZE:SIZ_ID',
    ADD COLUMN `CG_CARGO_UOM_QTY` VARCHAR(35) DEFAULT NULL COMMENT 'UOM Quantity';

-- Add foreign key constraints for the new references
ALTER TABLE `T_CK_CT_TRIP_CARGO_MM`
    ADD CONSTRAINT `FK_CK_CT_TRIP_CARGO_MM_UOM_WEIGHT`
        FOREIGN KEY (`CG_CARGO_UOM_WEIGHT`) REFERENCES `T_CK_CT_MST_UOM_WEIGHT` (`WEI_ID`),
    ADD CONSTRAINT `FK_CK_CT_TRIP_CARGO_MM_UOM_VOLUME`
        FOREIGN KEY (`CG_CARGO_UOM_VOLUME`) REFERENCES `T_CK_CT_MST_UOM_VOLUME` (`VOL_ID`),
    ADD CONSTRAINT `FK_CK_CT_TRIP_CARGO_MM_UOM_SIZE`
        FOREIGN KEY (`CG_CARGO_UOM_SIZE`) REFERENCES `T_CK_CT_MST_UOM_SIZE` (`SIZ_ID`);

